python3 -c '
import os, glob

for root, dirs, files in os.walk("."):
    dirs[:] = [d for d in dirs if d not in [".git", "tmp", "log", "storage", "vendor", "node_modules"]]
    for f in files:
        if f.endswith((".rb", ".erb", ".js", ".yml", ".css", ".jbuilder")):
            path = os.path.join(root, f)
            try:
                content = open(path).read()
                lines = content.splitlines()
                for i in range(len(lines) - 1):
                    if lines[i].strip() == "" and lines[i+1].strip() == "":
                        print(f"{path}:{i+1}")
            except Exception:
                pass
'

